<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,reactive,ref,watch,nextTick} from 'vue'
import {ShieldCheck,UserRound,Users,Layers3,KeyRound,Monitor,ScrollText,RefreshCw,Plus,Search,ChevronRight,X,LogOut,Check,LockKeyhole,ArrowLeft,Boxes,Ban} from 'lucide-vue-next'
import {useHost,createApiClient,createIdempotencyKey,ApiError} from '@minhanos/app-sdk'
import {createIdentityClient} from '@minhanos/api-client/identity'
import type {IdentityUser,IdentityAccess,IdentityGroup,IdentityRole,IdentityRoleBinding,IdentitySession,IdentityCredentialRef,IdentityAuditEvent,IdentityPermission} from '@minhanos/shared-types'
import catalogs from '../locales/catalogs.json'

const props=withDefaults(defineProps<{embedded?:boolean;active?:boolean;apiBase?:string;panel?:boolean;section?:"profile"|"users"|"groups"|"roles"|"apps"|"sessions"|"security"|"audit"}>(),{embedded:false,active:true,apiBase:'/api'})
const emit=defineEmits<{(e:'session-ended'):void;(e:'profile-changed',name:string):void}>()
const host=useHost(),unregister=host.useCatalog('accounts',catalogs)
const t=(key:string,params?:Record<string,string|number>)=>{host.profile.value.locale;return host.i18n.t('accounts.'+key,params)}
const translated=(key:string,fallback:string)=>('accounts.'+key in catalogs['vi-VN'])?t(key):fallback
const legacy=createApiClient(props.apiBase),api=createIdentityClient(props.apiBase+'/v1/identity')
type Tab='profile'|'users'|'groups'|'roles'|'apps'|'sessions'|'security'|'audit'
const tab=ref<Tab>(props.section??'profile'),busy=ref(false),loading=ref(false),ready=ref(false),error=ref(''),notice=ref('')
const sessionUser=ref<{username:string;displayName:string}|null>(null),me=ref<IdentityUser|null>(null),access=ref<IdentityAccess|null>(null)
const loginName=ref(''),loginPassword=ref(''),profileName=ref(''),currentPassword=ref(''),newPassword=ref(''),repeatPassword=ref(''),reauthPassword=ref('')
const users=ref<IdentityUser[]>([]),groups=ref<IdentityGroup[]>([]),roles=ref<IdentityRole[]>([]),bindings=ref<IdentityRoleBinding[]>([]),sessions=ref<IdentitySession[]>([]),credentials=ref<IdentityCredentialRef[]>([]),audit=ref<IdentityAuditEvent[]>([]),permissions=ref<IdentityPermission[]>([])
const selectedGroup=ref<IdentityGroup|null>(null),members=ref<{userId:string}[]>([]),search=ref(''),userOptions=ref<IdentityUser[]>([])
const cursors=reactive<Record<string,string|null>>({users:null,groups:null,roles:null,bindings:null,sessions:null,credentials:null,audit:null,members:null})
const fields=reactive<Record<string,string>>({}),rolePermissions=ref<string[]>([])
// User detail page (Users tab): one user with effective access, groups and recent activity.
type UserDetail={user:IdentityUser;access:IdentityAccess|null;groups:IdentityGroup[]|null;events:IdentityAuditEvent[]|null;sessions:IdentitySession[]|null}
const detailId=ref(''),detail=ref<UserDetail|null>(null)
// Apps tab: first-party apps, deny rules of governed apps (Files) and display names of rule subjects.
type AppEntry={appId:string;displayName:string;allowed:boolean};type AppRule={id:string;appId:string;effect:'deny';subject:{kind:'user'|'group'|'role';id:string};version:number}
const FILES_APP='com.minhanos.files',appList=ref<AppEntry[]>([]),appRules=ref<AppRule[]>([]),subjectNames=reactive<Record<string,string>>({})
type Dialog={title:string;hint?:string;kind:string;reauth:boolean;key:string;submit:()=>Promise<void>}
const dialog=ref<Dialog|null>(null),dialogPanel=ref<HTMLElement|null>(null)
let revision=0,disposed=false,ended=false,priorFocus:HTMLElement|null=null
const has=(permission:string)=>access.value?.permissions.includes(permission)===true
// Locale/theme are Platform-owned (ADR 0007): inside a Shell with Settings, edit them there; standalone keeps local selectors.
const settingsAvailable=ref(false)
const policyAdmin=computed(()=>access.value?.baseRole==='system-admin')
const nav=computed(()=>me.value?.passwordChangeRequired?[{id:'security' as Tab,icon:KeyRound,visible:true}]:[
 {id:'profile',icon:UserRound,visible:true},{id:'users',icon:Users,visible:has('identity.users.read')},{id:'groups',icon:Layers3,visible:has('identity.groups.read')},
 {id:'roles',icon:ShieldCheck,visible:has('identity.roles.read')},{id:'apps',icon:Boxes,visible:has('identity.apps.read')},{id:'sessions',icon:Monitor,visible:has('identity.sessions.read')},{id:'security',icon:KeyRound,visible:true},{id:'audit',icon:ScrollText,visible:has('identity.audit.read')}
].filter(v=>v.visible) as {id:Tab;icon:typeof UserRound;visible:boolean}[])
const dirty=computed(()=>!!dialog.value||!!(me.value&&profileName.value!==me.value.displayName)||!!currentPassword.value||!!newPassword.value||!!repeatPassword.value)
function clearSecrets(){loginPassword.value='';reauthPassword.value='';currentPassword.value='';newPassword.value='';repeatPassword.value='';fields.password='';fields.repeat=''}
function expire(){clearSecrets();sessionUser.value=null;me.value=null;access.value=null;dialog.value=null;users.value=[];groups.value=[];roles.value=[];bindings.value=[];sessions.value=[];credentials.value=[];audit.value=[];members.value=[];selectedGroup.value=null;detailId.value='';detail.value=null;legacy.setCSRF('');api.setCSRF('');tab.value=props.section??'profile';notice.value=t('session.ended');if(props.embedded&&!ended&&!disposed){ended=true;emit('session-ended');host.emit('session-ended')}}
function message(e:unknown){if(e instanceof ApiError){if(e.code==='AUTH_REQUIRED')expire();return translated('errors.'+e.code,host.errorMessage(e))}if(e instanceof Error&&e.message==='choose-user')return t('errors.chooseUser');if(e instanceof Error&&e.message==='choose-subject')return t('errors.chooseSubject');if(e instanceof Error&&e.message==='password-mismatch')return t('errors.passwordMismatch');if(e instanceof Error&&e.message==='password-length')return t('errors.invalidPassword');return t('errors.network')}
function date(value:string|null){host.profile.value.locale;return value?host.i18n.formatDate(value,{dateStyle:'medium',timeStyle:'short'}):t('unknown')}
const etag=(version:number)=>'"'+version+'"'
async function init(){
 try{const s=await legacy.request<{user:{username:string;displayName:string};csrfToken:string}>('/session');if(disposed)return;sessionUser.value=s.user;legacy.setCSRF(s.csrfToken);api.setCSRF(s.csrfToken)
  const [user,grants]=await Promise.all([api.identityGetMe(),api.identityGetMyAccess(),host.loadProfile(legacy.request)]);if(disposed)return;me.value=user;access.value=grants;profileName.value=user.displayName;if(user.passwordChangeRequired)tab.value='security';ended=false;await load(tab.value)
 }catch(e){if(!(e instanceof ApiError&&e.code==='AUTH_REQUIRED'))error.value=message(e);else expire()}finally{ready.value=true}
}
async function login(){if(busy.value)return;busy.value=true;error.value='';try{const s=await legacy.request<{csrfToken:string}>('/login',{method:'POST',body:JSON.stringify({username:loginName.value,password:loginPassword.value})});legacy.setCSRF(s.csrfToken);api.setCSRF(s.csrfToken);await init()}catch(e){error.value=message(e)}finally{loginPassword.value='';busy.value=false}}
async function logout(){if(!canClose())return;busy.value=true;try{await legacy.request('/logout',{method:'POST',body:'{}'});expire()}catch(e){error.value=message(e)}finally{busy.value=false}}
async function load(kind:Tab|'bindings'|'members',more=false){
 if(!access.value)return;const stamp=++revision;loading.value=true;error.value=''
 const cursor=more?cursors[kind]||undefined:undefined
 try{
  if(kind==='profile'){const draft=profileName.value,wasDirty=profileName.value!==me.value?.displayName;const u=await api.identityGetMe();if(stamp!==revision||disposed)return;me.value=u;if(!wasDirty&&profileName.value===draft)profileName.value=u.displayName}
  if(kind==='users'){const p=await api.identityListUsers({limit:50,search:search.value,cursor});if(stamp!==revision||disposed)return;users.value=more?[...users.value,...p.items]:p.items;cursors.users=p.nextCursor}
  if(kind==='groups'){const p=await api.identityListGroups({limit:50,cursor});if(stamp!==revision||disposed)return;groups.value=more?[...groups.value,...p.items]:p.items;cursors.groups=p.nextCursor}
  if(kind==='roles'){const [r,b,p]=await Promise.all([api.identityListRoles({limit:100,cursor}),api.identityListRoleBindings({limit:50}),api.identityListPermissions({limit:100})]);if(stamp!==revision||disposed)return;roles.value=more?[...roles.value,...r.items]:r.items;cursors.roles=r.nextCursor;bindings.value=b.items;cursors.bindings=b.nextCursor;permissions.value=p.items}
  if(kind==='bindings'){const p=await api.identityListRoleBindings({limit:50,cursor});if(stamp!==revision||disposed)return;bindings.value=more?[...bindings.value,...p.items]:p.items;cursors.bindings=p.nextCursor}
  if(kind==='sessions'){const p=await api.identityListMySessions({limit:50,cursor});if(stamp!==revision||disposed)return;sessions.value=more?[...sessions.value,...p.items]:p.items;cursors.sessions=p.nextCursor}
  if(kind==='security'){const p=await api.identityListMyCredentials({limit:50,cursor:more?cursors.credentials||undefined:undefined});if(stamp!==revision||disposed)return;credentials.value=more?[...credentials.value,...p.items]:p.items;cursors.credentials=p.nextCursor}
  if(kind==='apps'){const [list,rules,g,r]=await Promise.all([api.identityListApplications({limit:50}),api.identityListAppAccess({appId:FILES_APP}),has('identity.groups.read')?api.identityListGroups({limit:100}):Promise.resolve(null),has('identity.roles.read')?api.identityListRoles({limit:100}):Promise.resolve(null)]);if(stamp!==revision||disposed)return;appList.value=list.items;appRules.value=rules.items as AppRule[];if(g)groups.value=g.items;if(r)roles.value=r.items;await nameSubjects()}
  if(kind==='audit'){const p=await api.identityListAuditEvents({limit:50,cursor});if(stamp!==revision||disposed)return;audit.value=more?[...audit.value,...p.items]:p.items;cursors.audit=p.nextCursor}
  if(kind==='members'&&selectedGroup.value){const id=selectedGroup.value.id;const [p,g]=await Promise.all([api.identityListGroupMembers({groupId:id,limit:50,cursor}),api.identityGetGroup({groupId:id})]);if(stamp!==revision||disposed||selectedGroup.value?.id!==id)return;members.value=more?[...members.value,...p.items]:p.items;selectedGroup.value=g;cursors.members=p.nextCursor}
 }catch(e){error.value=message(e)}finally{if(stamp===revision)loading.value=false}
}
async function navigate(next:Tab){if(busy.value||dialog.value)return;tab.value=next;detailId.value='';detail.value=null;notice.value='';await load(next)}
async function saveProfile(){if(!me.value||busy.value)return;busy.value=true;error.value='';try{const u=await api.identityPatchMe({ifMatch:etag(me.value.version),body:{displayName:profileName.value}});me.value=u;profileName.value=u.displayName;if(sessionUser.value)sessionUser.value.displayName=u.displayName;emit('profile-changed',u.displayName);host.emit('profile-changed',{displayName:u.displayName});notice.value=t('saved')}catch(e){error.value=message(e)}finally{busy.value=false}}
async function profilePreference(event:Event,field:'locale'|'theme'){if(busy.value)return;busy.value=true;try{const value=(event.target as HTMLSelectElement).value;if(sessionUser.value)await host.updateProfile(legacy.request,{[field]:value});else host.applyProfile({...host.profile.value,[field]:value})}catch(e){error.value=message(e)}finally{busy.value=false}}
function open(title:string,kind:string,submit:()=>Promise<void>,values:Record<string,string>={},reauth=true,hint?:string){
 if(busy.value)return;priorFocus=document.activeElement as HTMLElement|null;for(const key of Object.keys(fields))delete fields[key];Object.assign(fields,values);rolePermissions.value=[];userOptions.value=[];reauthPassword.value='';error.value='';dialog.value={title,kind,submit,reauth,hint,key:createIdempotencyKey()};void nextTick(()=>dialogPanel.value?.querySelector<HTMLElement>('input,select,button')?.focus())
}
watch(fields,()=>{if(dialog.value&&!busy.value)dialog.value.key=createIdempotencyKey()},{deep:true})
watch(rolePermissions,()=>{if(dialog.value&&!busy.value)dialog.value.key=createIdempotencyKey()},{deep:true})
watch(()=>props.active,active=>{if(!active)reauthPassword.value=''})
function closeDialog(){if(busy.value)return;dialog.value=null;reauthPassword.value='';fields.password='';fields.repeat='';priorFocus?.focus()}
async function submitDialog(){if(!dialog.value||busy.value)return;const action=dialog.value;busy.value=true;error.value='';try{if(action.reauth)await api.identityReauthenticate({body:{password:reauthPassword.value}});reauthPassword.value='';await action.submit();if(!disposed){dialog.value=null;fields.password='';fields.repeat='';notice.value=t('saved');priorFocus?.focus()}}catch(e){error.value=message(e)}finally{reauthPassword.value='';busy.value=false}}
function newUser(){open(t('users.new'),'user',async()=>{await api.identityCreateUser({idempotencyKey:dialog.value!.key,body:{username:fields.username,displayName:fields.name,password:fields.password}});await load('users')},{username:'',name:'',password:''})}
function renameUser(u:IdentityUser){open(t('actions.edit'),'name',async()=>{const saved=await api.identityPatchUser({userId:u.id,ifMatch:etag(u.version),body:{displayName:fields.name}});if(u.id===me.value?.id){me.value=saved;profileName.value=saved.displayName;emit('profile-changed',saved.displayName);host.emit('profile-changed',{displayName:saved.displayName})}await usersChanged()},{name:u.displayName})}
function userState(u:IdentityUser,operation:'disable'|'enable'|'delete'){
 open(t('actions.'+operation),'confirm',async()=>{const args={userId:u.id,ifMatch:etag(u.version),idempotencyKey:dialog.value!.key};if(operation==='delete')await api.identitySoftDeleteUser(args);else if(operation==='disable')await api.identityDisableUser(args);else await api.identityEnableUser(args);if(u.id===me.value?.id&&operation!=='enable'){expire();return}await usersChanged()},{},true,operation==='delete'?t('confirm.delete'):operation==='disable'?t('confirm.disable'):u.displayName)
}
async function nameSubjects(){for(const rule of appRules.value){if(subjectNames[rule.subject.id])continue;if(rule.subject.kind==='group')subjectNames[rule.subject.id]=groups.value.find(g=>g.id===rule.subject.id)?.name??rule.subject.id;else if(rule.subject.kind==='role')subjectNames[rule.subject.id]=roleName(rule.subject.id);else{try{const u=await api.identityGetUser({userId:rule.subject.id});subjectNames[u.id]=u.displayName+' · @'+u.username}catch{subjectNames[rule.subject.id]=rule.subject.id}}}}
function denyApp(app:AppEntry){open(t('apps.deny'),'app-deny',async()=>{const kind=fields.subjectKind as 'user'|'group'|'role';const id=kind==='user'?fields.userId:kind==='group'?fields.groupId:fields.roleId;if(!id)throw new Error('choose-subject');await api.identityCreateAppAccess({appId:app.appId,idempotencyKey:dialog.value!.key,body:{subject:{kind,id}}});await load('apps')},{subjectKind:'user',userId:'',groupId:'',roleId:'',search:''},true,t('apps.denyHint',{app:app.displayName}));void lookupUsers()}
function allowAgain(rule:AppRule){open(t('apps.allow'),'confirm',async()=>{await api.identityDeleteAppAccess({appId:rule.appId,ruleId:rule.id,idempotencyKey:dialog.value!.key});await load('apps')},{},true,subjectNames[rule.subject.id]??rule.subject.id)}
async function usersChanged(){if(detailId.value)await loadDetail();else await load('users')}
async function openUser(u:IdentityUser){if(busy.value||dialog.value)return;detailId.value=u.id;detail.value=null;notice.value='';await loadDetail()}
async function closeUser(){if(busy.value||dialog.value)return;detailId.value='';detail.value=null;await load('users')}
async function loadDetail(){
 const id=detailId.value;if(!id)return;const stamp=++revision;loading.value=true;error.value=''
 try{
  const [user,grants,member,events,devices]=await Promise.all([api.identityGetUser({userId:id}),api.identityGetUserAccess({userId:id}),has('identity.groups.read')?api.identityListGroups({member:id,limit:100}):Promise.resolve(null),has('identity.audit.read')?api.identityListAuditEvents({target:id,limit:20}):Promise.resolve(null),has('identity.users.sessions.read')?api.identityListUserSessions({userId:id,limit:50}):Promise.resolve(null)])
  if(stamp!==revision||disposed||detailId.value!==id)return
  detail.value={user,access:grants,groups:member?.items??null,events:events?.items??null,sessions:devices?.items??null}
 }catch(e){error.value=message(e)}finally{if(stamp===revision)loading.value=false}
}
function resetPassword(u:IdentityUser){open(t('users.resetPassword'),'reset',async()=>{if(fields.password!==fields.repeat)throw new Error('password-mismatch');if([...fields.password].length<12||new TextEncoder().encode(fields.password).length>256)throw new Error('password-length');await api.identityResetUserPassword({userId:u.id,ifMatch:etag(u.version),idempotencyKey:dialog.value!.key,body:{newPassword:fields.password,requireChange:fields.requireChange!=='false'}});await usersChanged()},{password:'',repeat:'',requireChange:'true'},true,t('users.resetHint'))}
function revokeUserSessions(u:IdentityUser){open(t('users.signOutEverywhere'),'confirm',async()=>{await api.identityRevokeUserSessions({userId:u.id,idempotencyKey:dialog.value!.key});await usersChanged()},{},true,t('users.signOutHint'))}
async function userRole(u:IdentityUser){try{const a=await api.identityGetUserAccess({userId:u.id});open(t('actions.role'),'role',async()=>{await api.identitySetUserRole({userId:u.id,ifMatch:etag(u.version),idempotencyKey:dialog.value!.key,body:{role:fields.role as 'system-admin'|'user-admin'|'standard-user'}});if(u.id===me.value?.id){expire();return}await usersChanged()},{role:a.baseRole},true,t('profile.hostHint'))}catch(e){error.value=message(e)}}
function newGroup(){open(t('groups.new'),'group',async()=>{const g=await api.identityCreateGroup({idempotencyKey:dialog.value!.key,body:{key:fields.key,name:fields.name}});await load('groups');selectedGroup.value=g;await load('members')},{key:'',name:''})}
function renameGroup(g:IdentityGroup){open(t('actions.edit'),'name',async()=>{await api.identityPatchGroup({groupId:g.id,ifMatch:etag(g.version),body:{name:fields.name}});await load('groups');if(selectedGroup.value?.id===g.id)await load('members')},{name:g.name})}
function deleteGroup(g:IdentityGroup){open(t('groups.delete'),'confirm',async()=>{await api.identityDeleteGroup({groupId:g.id,ifMatch:etag(g.version),idempotencyKey:dialog.value!.key});if(selectedGroup.value?.id===g.id){selectedGroup.value=null;members.value=[]}await load('groups')},{},true,t('groups.deleteHint'))}
async function lookupUsers(){try{userOptions.value=(await api.identityListUsers({search:fields.search||'',limit:20})).items;fields.userId=''}catch(e){error.value=message(e)}}
function addMember(){if(!selectedGroup.value)return;const g=selectedGroup.value;open(t('actions.addMember'),'member',async()=>{if(!fields.userId)throw new Error('choose-user');await api.identityAddGroupMember({groupId:g.id,ifMatch:etag(g.version),idempotencyKey:dialog.value!.key,body:{userId:fields.userId}});await load('members')},{search:'',userId:''},true,t('groups.memberHint'));void lookupUsers()}
function removeMember(userId:string){if(!selectedGroup.value)return;const g=selectedGroup.value;open(t('actions.remove'),'confirm',async()=>{await api.identityRemoveGroupMember({groupId:g.id,userId,ifMatch:etag(g.version),idempotencyKey:dialog.value!.key});await load('members')},{},true,person(userId))}
function newRole(){open(t('roles.new'),'new-role',async()=>{await api.identityCreateRole({idempotencyKey:dialog.value!.key,body:{key:fields.key,name:fields.name,permissions:rolePermissions.value.slice()}});await load('roles')},{key:'',name:''},true,t('roles.ceiling'))}
const grantable=computed(()=>permissions.value.filter(p=>!['identity.roles.write','identity.groups.write','identity.apps.write'].includes(p.key)))
function newBinding(){open(t('actions.bind'),'binding',async()=>{await api.identityCreateRoleBinding({idempotencyKey:dialog.value!.key,body:{roleId:fields.roleId,subject:{kind:fields.subjectKind as 'user'|'group',id:fields.subjectKind==='user'?fields.userId:fields.groupId},scope:{kind:'system',id:null}}});await load('roles')},{roleId:'',subjectKind:'user',userId:'',groupId:'',search:''},true,t('roles.bindHint'));void lookupUsers();if(has('identity.groups.read'))void api.identityListGroups({limit:100}).then(p=>{groups.value=p.items}).catch(e=>{error.value=message(e)})}
function removeBinding(b:IdentityRoleBinding){open(t('actions.remove'),'confirm',async()=>{await api.identityDeleteRoleBinding({bindingId:b.id,ifMatch:etag(b.version),idempotencyKey:dialog.value!.key});await load('roles')},{},true,roleName(b.roleId))}
function revokeSession(s:IdentitySession){open(t('actions.revoke'),'confirm',async()=>{await api.identityRevokeMySession({sessionId:s.id});if(s.current){expire();return}await load('sessions')},{},false,t('confirm.revoke'))}
function revokeOthers(){open(t('actions.revokeOthers'),'confirm',async()=>{await api.identityRevokeOtherSessions({idempotencyKey:dialog.value!.key});await load('sessions')},{},false,t('confirm.revokeOthers'))}
async function changePassword(){if(busy.value)return;error.value='';if(newPassword.value!==repeatPassword.value){error.value=t('errors.passwordMismatch');return}if([...newPassword.value].length<12||new TextEncoder().encode(newPassword.value).length>256){error.value=t('errors.invalidPassword');return}busy.value=true;try{await api.identityChangePassword({idempotencyKey:createIdempotencyKey(),body:{currentPassword:currentPassword.value,newPassword:newPassword.value}});expire()}catch(e){error.value=message(e)}finally{currentPassword.value='';newPassword.value='';repeatPassword.value='';busy.value=false}}
function roleName(id:string){const role=roles.value.find(r=>r.id===id);return role?translated('roles.'+role.key,role.name):id}
function person(id:string){const u=users.value.find(v=>v.id===id)||userOptions.value.find(v=>v.id===id);return u?u.displayName+' · @'+u.username:id}
function canClose(){return !busy.value&&(!dirty.value||globalThis.confirm(t('confirm.discard')))}
defineExpose({canClose})
function beforeUnload(e:BeforeUnloadEvent){if(dirty.value||busy.value){e.preventDefault();e.returnValue=''}}
function dialogKeys(e:KeyboardEvent){if(!dialog.value||!props.active)return;if(e.key==='Escape'){e.preventDefault();closeDialog()}if(e.key==='Tab'){const nodes=[...(dialogPanel.value?.querySelectorAll<HTMLElement>('button:not([disabled]),input:not([disabled]),select:not([disabled])')||[])].filter(el=>el.getClientRects().length);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}}
onMounted(()=>{settingsAvailable.value=host.canOpenSettings();window.addEventListener('beforeunload',beforeUnload);void init()})
onBeforeUnmount(()=>{disposed=true;revision++;clearSecrets();unregister();window.removeEventListener('beforeunload',beforeUnload)})
</script>

<template>
 <section class="mn-accounts" :class="{embedded}" :aria-label="t('title')" @keydown="dialogKeys">
  <div v-if="!ready" class="ac-centered"><ShieldCheck :size="38"/><p>{{t('loading')}}</p></div>
  <div v-else-if="!sessionUser" class="ac-centered ac-login"><form class="ac-card" @submit.prevent="login"><div class="ac-logo"><ShieldCheck :size="30"/></div><span class="ac-eyebrow">{{t('title')}}</span><h1>{{t('login.title')}}</h1><p>{{t('login.hint')}}</p><p v-if="notice" role="status">{{notice}}</p><p v-if="error" role="alert" class="ac-error">{{error}}</p><label>{{t('fields.username')}}<input v-model="loginName" autocomplete="username" required :disabled="busy" maxlength="64"></label><label>{{t('fields.password')}}<input v-model="loginPassword" type="password" autocomplete="current-password" required :disabled="busy" maxlength="256"></label><button class="ac-primary" :disabled="busy">{{t(busy?'working':'actions.login')}}</button><label>{{t('fields.language')}}<select :value="host.profile.value.locale" @change="profilePreference($event,'locale')"><option value="vi-VN">Tiếng Việt</option><option value="en-US">English</option></select></label></form></div>
  <div v-else class="ac-layout" :class="{'ac-panel':panel}">
   <aside v-if="!panel" class="ac-sidebar"><div class="ac-brand"><span class="ac-logo"><ShieldCheck :size="25"/></span><div><strong>{{t('title')}}</strong><small>{{t('subtitle')}}</small></div></div><nav :aria-label="t('title')"><button v-for="item in nav" :key="item.id" :aria-current="tab===item.id?'page':undefined" :class="{selected:tab===item.id}" :disabled="busy||!!dialog" @click="navigate(item.id)"><component :is="item.icon" :size="19"/><span>{{t('nav.'+item.id)}}</span></button></nav><div class="ac-sidebar-footer"><span class="ac-avatar">{{sessionUser.displayName.slice(0,1)}}</span><div><strong>{{me?.displayName||sessionUser.displayName}}</strong><small>@{{sessionUser.username}}</small></div><button :aria-label="t('actions.logout')" :title="t('actions.logout')" :disabled="busy" @click="logout"><LogOut :size="18"/></button></div></aside>
   <main class="ac-main" :aria-busy="loading||busy"><header class="ac-header"><div><span class="ac-eyebrow">{{t('workspace')}}</span><h1>{{t('nav.'+tab)}}</h1><p>{{t('intro.'+tab)}}</p></div><div class="ac-header-actions"><button :aria-label="t('actions.refresh')" :title="t('actions.refresh')" :disabled="busy||loading||!!dialog" @click="me?(tab==='users'&&detailId?loadDetail():load(tab)):init()"><RefreshCw :size="18"/></button><button v-if="!panel" :aria-label="t('actions.logout')" :title="t('actions.logout')" :disabled="busy" @click="logout"><LogOut :size="18"/></button></div></header>
    <p v-if="notice" class="ac-notice" role="status"><Check :size="17"/>{{notice}}</p><p v-if="error&&!dialog" class="ac-error" role="alert">{{error}}</p><p v-if="loading" class="ac-muted" role="status">{{t('loading')}}</p>
    <template v-if="me&&access">
     <div v-if="tab==='profile'" class="ac-stack"><section class="ac-hero ac-card"><span class="ac-avatar large">{{me.displayName.slice(0,1)}}</span><div><span class="ac-eyebrow">{{t('profile.identity')}}</span><h2>{{me.displayName}}</h2><p>@{{me.username}}</p></div><span class="ac-pill">{{t('roles.'+access.baseRole)}}</span></section><div class="ac-columns"><form class="ac-card ac-stack" @submit.prevent="saveProfile"><h2>{{t('nav.profile')}}</h2><label>{{t('fields.displayName')}}<input v-model="profileName" required maxlength="100" :disabled="busy||!has('identity.self.write')"></label><button class="ac-primary" :disabled="busy||!has('identity.self.write')||profileName===me.displayName">{{t('actions.save')}}</button></form><section class="ac-card ac-stack"><h2>{{t('profile.access')}}</h2><p class="ac-inline"><ShieldCheck :size="20"/>{{t(access.hostOperator?'profile.hostOperator':'profile.noHostOperator')}}</p><p class="ac-muted">{{t('profile.hostHint')}}</p><button v-if="embedded&&settingsAvailable" type="button" @click="host.openSettings('com.minhanos.settings','language')">{{t('profile.openSettings')}}</button><template v-else><label>{{t('fields.language')}}<select :value="host.profile.value.locale" :disabled="busy" @change="profilePreference($event,'locale')"><option value="vi-VN">Tiếng Việt</option><option value="en-US">English</option></select></label><label>{{t('fields.theme')}}<select :value="host.profile.value.theme" :disabled="busy" @change="profilePreference($event,'theme')"><option v-for="mode in ['light','dark','system']" :key="mode" :value="mode">{{t('theme.'+mode)}}</option></select></label></template></section></div></div>
     <section v-if="tab==='users'&&!detailId" class="ac-card"><div class="ac-toolbar"><form class="ac-search" @submit.prevent="load('users')"><Search :size="17"/><input v-model="search" :placeholder="t('users.search')" :aria-label="t('users.search')" maxlength="100"><button :disabled="busy||loading">{{t('actions.search')}}</button></form><button v-if="has('identity.users.write')" class="ac-primary" :disabled="busy" @click="newUser"><Plus :size="17"/>{{t('users.new')}}</button></div><div class="ac-table-wrap"><table><thead><tr><th>{{t('fields.user')}}</th><th>{{t('fields.status')}}</th><th><span class="ac-sr">{{t('confirm.title')}}</span></th></tr></thead><tbody><tr v-for="u in users" :key="u.id"><td><button class="ac-name-link" :disabled="busy" :title="t('users.open')" @click="openUser(u)"><strong>{{u.displayName}}</strong><small>@{{u.username}}</small></button></td><td><span class="ac-pill" :class="u.status">{{t('status.'+u.status)}}</span></td><td class="ac-row-actions"><template v-if="has('identity.users.write')&&u.status!=='deleted'"><button :disabled="busy" @click="renameUser(u)">{{t('actions.edit')}}</button><button v-if="policyAdmin&&has('identity.roles.write')" :disabled="busy" @click="userRole(u)">{{t('actions.role')}}</button><button v-if="u.status==='active'" class="ac-danger" :disabled="busy" @click="userState(u,'disable')">{{t('actions.disable')}}</button><template v-else><button :disabled="busy" @click="userState(u,'enable')">{{t('actions.enable')}}</button><button class="ac-danger" :disabled="busy" @click="userState(u,'delete')">{{t('actions.delete')}}</button></template></template></td></tr></tbody></table><p v-if="!users.length&&!loading" class="ac-empty">{{t('empty')}}</p></div><div class="ac-list-footer"><small>{{t('items',{count:users.length})}}</small><button v-if="cursors.users" :disabled="loading" @click="load('users',true)">{{t('actions.more')}}</button></div></section>
     <section v-if="tab==='users'&&detailId" class="ac-stack" :aria-label="t('users.detail')"><div class="ac-toolbar"><button :disabled="busy" @click="closeUser"><ArrowLeft :size="17"/>{{t('users.back')}}</button></div><template v-if="detail"><section class="ac-hero ac-card"><span class="ac-avatar large">{{detail.user.displayName.slice(0,1)}}</span><div><span class="ac-eyebrow">{{t('users.detail')}}</span><h2>{{detail.user.displayName}}</h2><p>@{{detail.user.username}}</p></div><span class="ac-pill" :class="detail.user.status">{{t('status.'+detail.user.status)}}</span><span v-if="detail.user.passwordChangeRequired" class="ac-pill disabled">{{t('users.mustChange')}}</span></section><div v-if="has('identity.users.write')&&detail.user.status!=='deleted'" class="ac-card ac-row-actions ac-detail-actions"><button :disabled="busy" @click="renameUser(detail.user)">{{t('actions.edit')}}</button><button v-if="policyAdmin&&has('identity.roles.write')" :disabled="busy" @click="userRole(detail.user)">{{t('actions.role')}}</button><button v-if="detail.user.id!==me?.id" :disabled="busy" @click="resetPassword(detail.user)"><KeyRound :size="17"/>{{t('users.resetPassword')}}</button><button v-if="detail.user.status==='active'" class="ac-danger" :disabled="busy" @click="userState(detail.user,'disable')">{{t('actions.disable')}}</button><template v-else><button :disabled="busy" @click="userState(detail.user,'enable')">{{t('actions.enable')}}</button><button class="ac-danger" :disabled="busy" @click="userState(detail.user,'delete')">{{t('actions.delete')}}</button></template></div><div class="ac-columns"><section v-if="detail.access" class="ac-card ac-stack"><h2>{{t('users.access')}}</h2><p class="ac-inline"><ShieldCheck :size="20"/>{{t('roles.'+detail.access.baseRole)}}</p><p class="ac-muted">{{t(detail.access.hostOperator?'profile.hostOperator':'profile.noHostOperator')}}</p><ul class="ac-permissions"><li v-for="p in detail.access.permissions" :key="p"><Check :size="14"/>{{translated('permissions.'+p,p)}}</li></ul></section><section v-if="detail.groups" class="ac-card ac-stack"><h2>{{t('nav.groups')}}</h2><p v-for="g in detail.groups" :key="g.id" class="ac-inline"><Layers3 :size="18"/><span><strong>{{g.name}}</strong><small>{{g.key}}</small></span></p><p v-if="!detail.groups.length" class="ac-empty">{{t('users.noGroups')}}</p></section></div><section v-if="detail.sessions" class="ac-card"><div class="ac-toolbar"><h2>{{t('nav.sessions')}}</h2><button v-if="has('identity.users.sessions.revoke')&&detail.user.id!==me?.id" class="ac-danger" :disabled="busy||!detail.sessions.length" @click="revokeUserSessions(detail.user)">{{t('users.signOutEverywhere')}}</button></div><article v-for="s in detail.sessions" :key="s.id" class="ac-session"><span class="ac-logo"><Monitor :size="23"/></span><div><strong>{{s.realm==='desktop'?'MinhAnOS Desktop':'MinhAnOS Files'}}</strong><small>{{t('fields.created')}}: {{date(s.createdAt)}} · {{t('fields.expires')}}: {{date(s.expiresAt)}}</small></div></article><p v-if="!detail.sessions.length" class="ac-empty">{{t('users.noSessions')}}</p></section><section v-if="detail.events" class="ac-card"><h2>{{t('users.activity')}}</h2><div class="ac-table-wrap"><table><thead><tr><th>{{t('fields.action')}}</th><th>{{t('fields.result')}}</th><th>{{t('fields.time')}}</th></tr></thead><tbody><tr v-for="event in detail.events" :key="event.id"><td><strong>{{translated('audit.actions.'+event.action,event.action)}}</strong><small v-if="event.details.count">{{t('audit.attempts',{count:event.details.count})}}</small></td><td><span class="ac-pill" :class="event.outcome">{{t('status.'+event.outcome)}}</span></td><td>{{date(event.occurredAt)}}</td></tr></tbody></table></div><p v-if="!detail.events.length" class="ac-empty">{{t('empty')}}</p></section></template></section>
     <div v-if="tab==='groups'" class="ac-stack"><section class="ac-card"><div class="ac-toolbar"><h2>{{t('nav.groups')}}</h2><button v-if="policyAdmin&&has('identity.groups.write')" class="ac-primary" :disabled="busy" @click="newGroup"><Plus :size="17"/>{{t('groups.new')}}</button></div><div v-for="g in groups" :key="g.id" class="ac-list-row"><button class="ac-entry" @click="selectedGroup=g;load('members')"><Layers3 :size="21"/><span><strong>{{g.name}}</strong><small>{{g.key}}</small></span><ChevronRight :size="17"/></button><template v-if="policyAdmin&&has('identity.groups.write')&&g.kind==='user'"><button :disabled="busy" @click="renameGroup(g)">{{t('actions.edit')}}</button><button class="ac-danger" :disabled="busy" @click="deleteGroup(g)">{{t('groups.delete')}}</button></template></div><p v-if="!groups.length&&!loading" class="ac-empty">{{t('empty')}}</p><button v-if="cursors.groups" :disabled="loading" @click="load('groups',true)">{{t('actions.more')}}</button></section><section v-if="selectedGroup" class="ac-card"><div class="ac-toolbar"><h2>{{selectedGroup.name}} · {{t('actions.members')}}</h2><button v-if="policyAdmin&&has('identity.groups.write')" :disabled="busy" @click="addMember">{{t('actions.addMember')}}</button></div><div v-for="member in members" :key="member.userId" class="ac-list-row"><span class="ac-id">{{person(member.userId)}}</span><button v-if="policyAdmin&&has('identity.groups.write')" class="ac-danger" :disabled="busy" @click="removeMember(member.userId)">{{t('actions.remove')}}</button></div><p v-if="!members.length&&!loading" class="ac-empty">{{t('empty')}}</p><button v-if="cursors.members" :disabled="loading" @click="load('members',true)">{{t('actions.more')}}</button></section></div>
     <div v-if="tab==='roles'" class="ac-stack"><div class="ac-toolbar"><p class="ac-muted">{{t('roles.ceiling')}}</p><div class="ac-row-actions" v-if="policyAdmin&&has('identity.roles.write')"><button class="ac-primary" :disabled="busy" @click="newRole">{{t('roles.new')}}</button><button :disabled="busy" @click="newBinding">{{t('actions.bind')}}</button></div></div><div class="ac-role-grid"><article v-for="r in roles" :key="r.id" class="ac-card"><div class="ac-toolbar"><ShieldCheck :size="23"/><span class="ac-pill">{{t(r.protected?'status.protected':'status.custom')}}</span></div><h2>{{translated('roles.'+r.key,r.name)}}</h2><small>{{r.key}}</small><ul class="ac-permissions"><li v-for="p in r.permissions" :key="p"><Check :size="14"/>{{translated('permissions.'+p,p)}}</li></ul></article></div><button v-if="cursors.roles" :disabled="loading" @click="load('roles',true)">{{t('actions.more')}}</button><section class="ac-card"><h2>{{t('roles.bindings')}}</h2><p class="ac-muted">{{t('roles.bindHint')}}</p><div v-for="b in bindings" :key="b.id" class="ac-list-row"><div><strong>{{roleName(b.roleId)}}</strong><small>{{t('fields.'+b.subject.kind)}} · {{b.subject.kind==='user'?person(b.subject.id):groups.find(g=>g.id===b.subject.id)?.name||b.subject.id}}</small></div><button v-if="policyAdmin&&has('identity.roles.write')" class="ac-danger" :disabled="busy" @click="removeBinding(b)">{{t('actions.remove')}}</button></div><p v-if="!bindings.length&&!loading" class="ac-empty">{{t('empty')}}</p><button v-if="cursors.bindings" :disabled="loading" @click="load('bindings',true)">{{t('actions.more')}}</button></section></div>
     <div v-if="tab==='apps'" class="ac-stack"><article v-for="app in appList" :key="app.appId" class="ac-card ac-stack"><div class="ac-toolbar"><span class="ac-inline"><Boxes :size="22"/><span><strong>{{app.displayName}}</strong><small>{{app.appId}}</small></span></span><span class="ac-pill" :class="app.allowed?'active':'disabled'">{{t(app.allowed?'apps.allowedForYou':'apps.deniedForYou')}}</span></div><template v-if="app.appId===FILES_APP"><div class="ac-toolbar"><h2>{{t('apps.rules')}}</h2><button v-if="policyAdmin&&has('identity.apps.write')" class="ac-primary" :disabled="busy" @click="denyApp(app)"><Ban :size="17"/>{{t('apps.deny')}}</button></div><div v-for="rule in appRules" :key="rule.id" class="ac-list-row"><span class="ac-inline"><Ban :size="18"/><span><strong>{{subjectNames[rule.subject.id]??rule.subject.id}}</strong><small>{{t('fields.'+rule.subject.kind)}}</small></span></span><button v-if="policyAdmin&&has('identity.apps.write')" :disabled="busy" @click="allowAgain(rule)">{{t('apps.allow')}}</button></div><p v-if="!appRules.length" class="ac-empty">{{t('apps.noRules')}}</p></template><p v-else class="ac-muted">{{t('apps.protected')}}</p></article></div>
     <section v-if="tab==='sessions'" class="ac-card"><div class="ac-toolbar"><h2>{{t('nav.sessions')}}</h2><button v-if="has('identity.sessions.revoke')" :disabled="busy||sessions.length<2" @click="revokeOthers">{{t('actions.revokeOthers')}}</button></div><article v-for="s in sessions" :key="s.id" class="ac-session"><span class="ac-logo"><Monitor :size="23"/></span><div><strong>{{s.realm==='desktop'?'MinhAnOS Desktop':'MinhAnOS Files'}} <span v-if="s.current" class="ac-pill">{{t('status.current')}}</span></strong><p>{{s.deviceHint||t('unknown')}}</p><small>{{t('fields.created')}}: {{date(s.createdAt)}} · {{t('fields.expires')}}: {{date(s.expiresAt)}}</small></div><button v-if="has('identity.sessions.revoke')" class="ac-danger" :disabled="busy" @click="revokeSession(s)">{{t('actions.revoke')}}</button></article><p v-if="!sessions.length&&!loading" class="ac-empty">{{t('empty')}}</p><button v-if="cursors.sessions" :disabled="loading" @click="load('sessions',true)">{{t('actions.more')}}</button></section>
     <p v-if="tab==='security'&&me?.passwordChangeRequired" class="ac-notice" role="alert"><LockKeyhole :size="17"/>{{t('security.changeRequired')}}</p><div v-if="tab==='security'" class="ac-columns"><form v-if="has('identity.password.change')" class="ac-card ac-stack" @submit.prevent="changePassword"><span class="ac-logo"><LockKeyhole :size="25"/></span><h2>{{t('actions.password')}}</h2><p class="ac-muted">{{t('security.passwordHint')}}</p><label>{{t('fields.currentPassword')}}<input v-model="currentPassword" type="password" autocomplete="current-password" required maxlength="256" :disabled="busy"></label><label>{{t('fields.newPassword')}}<input v-model="newPassword" type="password" autocomplete="new-password" required minlength="12" maxlength="256" :disabled="busy"></label><label>{{t('fields.repeatPassword')}}<input v-model="repeatPassword" type="password" autocomplete="new-password" required minlength="12" maxlength="256" :disabled="busy"></label><p class="ac-muted">{{t('session.logoutAll')}}</p><button class="ac-primary" :disabled="busy">{{t('actions.password')}}</button></form><section class="ac-card ac-stack"><h2>{{t('security.credentials')}}</h2><div v-for="c in credentials" :key="c.id" class="ac-credential"><KeyRound :size="20"/><div><strong>{{c.kind==='password'?t('security.localPassword'):c.kind}}</strong><small>{{t('security.lastChanged')}}: {{date(c.lastChangedAt)}}</small></div><span class="ac-pill">{{translated('status.'+c.state,c.state)}}</span></div><p class="ac-muted">{{t('security.unsupported')}}</p><button v-if="cursors.credentials" :disabled="loading" @click="load('security',true)">{{t('actions.more')}}</button></section></div>
     <section v-if="tab==='audit'" class="ac-card"><div class="ac-table-wrap"><table><thead><tr><th>{{t('fields.action')}}</th><th>{{t('fields.actor')}}</th><th>{{t('fields.result')}}</th><th>{{t('fields.time')}}</th></tr></thead><tbody><tr v-for="event in audit" :key="event.id"><td><strong>{{translated('audit.actions.'+event.action,event.action)}}</strong><small v-if="event.details.count">{{t('audit.attempts',{count:event.details.count})}}</small><small class="ac-id" :title="event.targetId||''">{{event.targetId||t('unknown')}}</small></td><td class="ac-id" :title="event.actorId||''">{{event.actorId?person(event.actorId):t('unknown')}}</td><td><span class="ac-pill" :class="event.outcome">{{t('status.'+event.outcome)}}</span></td><td>{{date(event.occurredAt)}}</td></tr></tbody></table></div><p v-if="!audit.length&&!loading" class="ac-empty">{{t('empty')}}</p><button v-if="cursors.audit" :disabled="loading" @click="load('audit',true)">{{t('actions.more')}}</button></section>
    </template>
   </main>
  </div>
  <div v-if="dialog&&active" class="ac-overlay" @click.self="closeDialog"><form ref="dialogPanel" class="ac-dialog ac-stack" role="dialog" aria-modal="true" aria-labelledby="ac-dialog-title" @submit.prevent="submitDialog"><div class="ac-toolbar"><h2 id="ac-dialog-title">{{dialog.title}}</h2><button type="button" :aria-label="t('actions.close')" :disabled="busy" @click="closeDialog"><X :size="18"/></button></div><p v-if="dialog.hint" class="ac-muted">{{dialog.hint}}</p><p v-if="error" role="alert" class="ac-error">{{error}}</p>
   <fieldset :disabled="busy" class="ac-stack"><template v-if="['user','name','group','new-role'].includes(dialog.kind)"><label>{{t('fields.name')}}<input v-model="fields.name" required maxlength="100"></label></template><template v-if="dialog.kind==='user'"><label>{{t('fields.username')}}<input v-model="fields.username" pattern="[a-z][a-z0-9_-]{2,31}" required minlength="3" maxlength="32" autocomplete="off"></label><label>{{t('fields.password')}}<input v-model="fields.password" type="password" autocomplete="new-password" required minlength="12" maxlength="256"></label></template><label v-if="['group','new-role'].includes(dialog.kind)">{{t('fields.key')}}<input v-model="fields.key" pattern="[a-z][a-z0-9]*(?:[.\-][a-z0-9]+)*" required maxlength="100"></label>
   <template v-if="dialog.kind==='reset'"><label>{{t('fields.newPassword')}}<input v-model="fields.password" type="password" autocomplete="new-password" required minlength="12" maxlength="256"></label><label>{{t('fields.repeatPassword')}}<input v-model="fields.repeat" type="password" autocomplete="new-password" required minlength="12" maxlength="256"></label><label class="ac-check"><input v-model="fields.requireChange" type="checkbox" true-value="true" false-value="false">{{t('users.requireChange')}}</label></template>
   <template v-if="dialog.kind==='app-deny'"><label>{{t('fields.subjectKind')}}<select v-model="fields.subjectKind"><option value="user">{{t('fields.user')}}</option><option v-if="has('identity.groups.read')" value="group">{{t('fields.group')}}</option><option v-if="has('identity.roles.read')" value="role">{{t('fields.role')}}</option></select></label><label v-if="fields.subjectKind==='group'">{{t('fields.group')}}<select v-model="fields.groupId" required><option value="" disabled>{{t('fields.group')}}</option><option v-for="g in groups" :key="g.id" :value="g.id">{{g.name}}</option></select></label><label v-if="fields.subjectKind==='role'">{{t('fields.role')}}<select v-model="fields.roleId" required><option value="" disabled>{{t('fields.role')}}</option><option v-for="r in roles" :key="r.id" :value="r.id">{{roleName(r.id)}}</option></select></label></template>
   <label v-if="dialog.kind==='role'">{{t('fields.role')}}<select v-model="fields.role" required><option v-for="role in ['standard-user','user-admin','system-admin']" :key="role" :value="role">{{t('roles.'+role)}}</option></select></label>
   <template v-if="dialog.kind==='new-role'"><span>{{t('fields.permissions')}}</span><div class="ac-checks"><label v-for="p in grantable" :key="p.key"><input v-model="rolePermissions" type="checkbox" :value="p.key">{{translated('permissions.'+p.key,p.key)}}</label></div></template>
   <template v-if="dialog.kind==='binding'"><label>{{t('fields.role')}}<select v-model="fields.roleId" required><option value="" disabled>{{t('fields.role')}}</option><option v-for="r in roles.filter(r=>!r.protected||r.key==='user-admin')" :key="r.id" :value="r.id">{{roleName(r.id)}}</option></select></label><label>{{t('fields.subjectKind')}}<select v-model="fields.subjectKind"><option value="user">{{t('fields.user')}}</option><option value="group">{{t('fields.group')}}</option></select></label><label v-if="fields.subjectKind==='group'">{{t('fields.group')}}<select v-model="fields.groupId" required><option value="" disabled>{{t('fields.group')}}</option><option v-for="g in groups.filter(g=>g.kind==='user')" :key="g.id" :value="g.id">{{g.name}}</option></select></label><small>{{t('fields.scope')}}: {{t('roles.systemScope')}}</small></template>
   <template v-if="dialog.kind==='member'||(dialog.kind==='binding'||dialog.kind==='app-deny')&&fields.subjectKind==='user'"><div class="ac-search"><input v-model="fields.search" :placeholder="t('users.search')" :aria-label="t('users.search')" maxlength="100"><button type="button" @click="lookupUsers">{{t('actions.search')}}</button></div><label>{{t('fields.user')}}<select v-model="fields.userId" required><option value="" disabled>{{t('errors.chooseUser')}}</option><option v-for="u in userOptions" :key="u.id" :value="u.id">{{u.displayName}} · @{{u.username}}</option></select></label></template>
   <label v-if="dialog.reauth">{{t('fields.currentPassword')}}<input v-model="reauthPassword" type="password" autocomplete="current-password" required maxlength="256"><small>{{t('confirm.reauth')}}</small></label></fieldset><footer class="ac-dialog-actions"><button type="button" :disabled="busy" @click="closeDialog">{{t('actions.cancel')}}</button><button class="ac-primary" :disabled="busy">{{t(busy?'working':'actions.confirm')}}</button></footer></form></div>
 </section>
</template>
